import { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { getResults, getJob, updateShortlist } from "../services/api";

function ScoreRing({ score, color = "var(--blue-2)", size = 56 }) {
  const r = 20, circ = 2 * Math.PI * r;
  const dash = (score / 100) * circ;
  return (
    <div style={{ position:"relative", width:size, height:size, flexShrink:0 }}>
      <svg width={size} height={size} viewBox="0 0 56 56">
        <circle cx="28" cy="28" r={r} fill="none" stroke="rgba(255,255,255,0.05)" strokeWidth="4"/>
        <circle cx="28" cy="28" r={r} fill="none" stroke={color} strokeWidth="4"
          strokeDasharray={`${dash} ${circ}`} strokeLinecap="round"
          transform="rotate(-90 28 28)" style={{ transition:"stroke-dasharray 0.8s ease" }}/>
      </svg>
      <div style={{
        position:"absolute", inset:0, display:"flex", alignItems:"center", justifyContent:"center",
        fontFamily:"Syne", fontWeight:700, fontSize:13, color:"var(--text-1)",
      }}>{Math.round(score)}</div>
    </div>
  );
}

function PassivityBadge({ score, label }) {
  const cfg = score >= 70
    ? { color:"#FCD34D", bg:"rgba(217,119,6,0.12)", border:"rgba(217,119,6,0.25)" }
    : score >= 40
    ? { color:"var(--blue-3)", bg:"rgba(37,99,235,0.1)", border:"rgba(37,99,235,0.2)" }
    : { color:"var(--teal-2)", bg:"rgba(13,148,136,0.1)", border:"rgba(13,148,136,0.2)" };
  return (
    <div style={{ display:"inline-flex", alignItems:"center", gap:5, background:cfg.bg, borderRadius:8, padding:"3px 9px", border:`1px solid ${cfg.border}` }}>
      <div style={{ width:5, height:5, borderRadius:"50%", background:cfg.color }} />
      <span style={{ fontSize:11, fontWeight:700, color:cfg.color, fontFamily:"Syne" }}>{label}</span>
    </div>
  );
}

function ExplainPanel({ breakdown, onClose }) {
  if (!breakdown) return null;
  return (
    <div style={{
      position:"fixed", inset:0, background:"rgba(0,0,0,0.75)", zIndex:300,
      display:"flex", alignItems:"center", justifyContent:"center", padding:24,
      animation:"fadeIn 0.2s ease",
    }} onClick={onClose}>
      <div style={{
        background:"var(--navy-2)", borderRadius:20, padding:40,
        maxWidth:580, width:"100%", border:"1px solid var(--border-2)",
        maxHeight:"85vh", overflowY:"auto",
      }} onClick={e => e.stopPropagation()}>
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:28 }}>
          <h3 style={{ fontFamily:"Syne", fontWeight:800, fontSize:20, color:"var(--text-1)" }}>Score Breakdown</h3>
          <button onClick={onClose} style={{ background:"none", border:"none", color:"var(--text-3)", cursor:"pointer", fontSize:22 }}>×</button>
        </div>

        {/* Score cards */}
        <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:16, marginBottom:28 }}>
          {[{ label:"Job Fit", val:breakdown.fit_score, color:"var(--blue-2)" },
            { label:"Passivity", val:breakdown.passivity_score, color:"#FCD34D" }].map(s => (
            <div key={s.label} style={{ background:"var(--navy-3)", borderRadius:14, padding:20, border:"1px solid var(--border)", textAlign:"center" }}>
              <ScoreRing score={s.val} color={s.color} size={68}/>
              <div style={{ marginTop:10, fontSize:11, color:"var(--text-2)", fontFamily:"Syne", fontWeight:700, textTransform:"uppercase", letterSpacing:"0.08em" }}>{s.label}</div>
            </div>
          ))}
        </div>

        {/* Ranking basis */}
        <div style={{ background:"rgba(37,99,235,0.08)", border:"1px solid rgba(37,99,235,0.18)", borderRadius:10, padding:"12px 16px", marginBottom:24, fontSize:12, color:"var(--blue-3)", fontFamily:"Syne", fontWeight:600 }}>
          📌 {breakdown.ranking_basis}
        </div>

        {/* Fit */}
        <div style={{ marginBottom:24 }}>
          <div className="label" style={{ marginBottom:8 }}>Qualification Match</div>
          <div style={{ background:"var(--navy-3)", borderRadius:10, padding:16, fontSize:13, color:"var(--text-2)", lineHeight:1.7, border:"1px solid var(--border)" }}>
            {breakdown.fit_explanation}
          </div>
        </div>

        {/* Passivity */}
        <div>
          <div className="label" style={{ marginBottom:4 }}>{breakdown.passivity_context_title}</div>
          <div style={{ fontSize:12, color:"var(--text-3)", marginBottom:12 }}>{breakdown.passivity_context_note}</div>
          <div style={{ display:"grid", gap:8 }}>
            {(breakdown.passivity_factors || []).map((f, i) => (
              <div key={i} style={{ background:"var(--navy-3)", borderRadius:10, padding:"12px 14px", border:"1px solid var(--border)", display:"flex", gap:12 }}>
                <span style={{ fontSize:15, marginTop:1 }}>{f.impact === "positive" ? "✅" : f.impact === "negative" ? "⚠️" : "ℹ️"}</span>
                <div>
                  <div style={{ fontFamily:"Syne", fontWeight:700, fontSize:13, color:"var(--text-1)", marginBottom:2 }}>{f.factor}</div>
                  <div style={{ fontSize:12, color:"var(--text-2)" }}>{f.detail}</div>
                </div>
              </div>
            ))}
          </div>
        </div>

        <div style={{ marginTop:24, padding:"14px 16px", background:"var(--navy-3)", borderRadius:10, border:"1px solid var(--border)", fontSize:13, color:"var(--text-2)", lineHeight:1.6 }}>
          {breakdown.summary}
        </div>
      </div>
    </div>
  );
}

export default function Results() {
  const { jobId } = useParams();
  const navigate = useNavigate();
  const [candidates, setCandidates] = useState([]);
  const [job, setJob] = useState(null);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState({ skill_filter:"", seniority:"" });
  const [selected, setSelected] = useState(null);
  const [shortlisted, setShortlisted] = useState(new Set());

  useEffect(() => {
    Promise.all([getJob(jobId), getResults(jobId)])
      .then(([j, r]) => { setJob(j.data); setCandidates(r.data); })
      .catch(() => alert("Could not load results."))
      .finally(() => setLoading(false));
  }, [jobId]);

  const applyFilters = async () => {
    const params = {};
    if (filters.skill_filter) params.skill_filter = filters.skill_filter;
    if (filters.seniority)    params.seniority = filters.seniority;
    const res = await getResults(jobId, params);
    setCandidates(res.data);
  };

  const toggleShortlist = async (c) => {
    const newStatus = shortlisted.has(c.id) ? "pending" : "approved";
    await updateShortlist(jobId, c.id, newStatus);
    setShortlisted(s => { const n = new Set(s); newStatus === "approved" ? n.add(c.id) : n.delete(c.id); return n; });
  };

  const viewCV = (candidateId, sourceFile) => {
    if (!sourceFile || sourceFile === "csv_import") {
      alert("No individual CV file stored for this candidate. This candidate was loaded from a CSV dataset.");
      return;
    }
    window.open(`http://localhost:8000/api/files/${candidateId}`, "_blank");
  };

  if (loading) return (
    <div style={{ textAlign:"center", padding:80, color:"var(--text-2)" }}>
      <div style={{ fontSize:36, marginBottom:16, animation:"spin 1s linear infinite", display:"inline-block" }}>⚙️</div>
      <div style={{ fontFamily:"Syne", fontSize:18 }}>Loading results...</div>
    </div>
  );

  return (
    <div className="page">
      {/* Header */}
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:36, flexWrap:"wrap", gap:16 }}>
        <div>
          <div className="section-tag" style={{ marginBottom:12 }}>Step 3 of 3 — AI Results</div>
          <h1 style={{ fontFamily:"Syne", fontWeight:800, fontSize:32, color:"var(--text-1)", marginBottom:6 }}>{job?.title || "Results"}</h1>
          <p style={{ color:"var(--text-2)", fontSize:15 }}>
            {candidates.length} candidates ranked by job-fit score · {shortlisted.size} shortlisted
          </p>
        </div>
        <div style={{ display:"flex", gap:10 }}>
          <button className="btn btn-secondary" onClick={() => navigate(`/upload/${jobId}`)}>← Re-upload</button>
          {shortlisted.size > 0 && (
            <button className="btn btn-primary" onClick={() => navigate(`/shortlist/${jobId}`)}>
              Review Shortlist ({shortlisted.size}) →
            </button>
          )}
        </div>
      </div>

      {/* Filters */}
      <div className="card" style={{ padding:"18px 24px", marginBottom:24, display:"flex", gap:16, alignItems:"flex-end", flexWrap:"wrap" }}>
        <div style={{ flex:1, minWidth:180 }}>
          <label className="label">Filter by skill</label>
          <input className="input" placeholder="e.g. Python, Java, Agile..."
            value={filters.skill_filter} onChange={e => setFilters(f => ({ ...f, skill_filter: e.target.value }))} />
        </div>
        <div style={{ width:180 }}>
          <label className="label">Seniority level</label>
          <select className="input" value={filters.seniority} onChange={e => setFilters(f => ({ ...f, seniority: e.target.value }))}>
            <option value="">All levels</option>
            <option value="senior">Senior</option>
            <option value="mid">Mid-level</option>
            <option value="junior">Junior</option>
          </select>
        </div>
        <button className="btn btn-primary" onClick={applyFilters}>Apply Filters</button>
        <button className="btn btn-secondary" onClick={() => { setFilters({ skill_filter:"", seniority:"" }); getResults(jobId).then(r => setCandidates(r.data)); }}>Clear</button>
      </div>

      {/* Candidates */}
      <div style={{ display:"grid", gap:12 }}>
        {candidates.map((c, i) => (
          <div key={c.id} className="card" style={{
            padding:"18px 24px", display:"flex", gap:20, alignItems:"center",
            animation:`fadeUp 0.4s ease ${i * 0.04}s both`,
            borderColor: shortlisted.has(c.id) ? "rgba(37,99,235,0.35)" : "var(--border)",
          }}>
            {/* Rank */}
            <div style={{
              width:38, height:38, borderRadius:10, flexShrink:0,
              background: i < 3 ? "rgba(37,99,235,0.15)" : "var(--navy-3)",
              display:"flex", alignItems:"center", justifyContent:"center",
              fontFamily:"Syne", fontWeight:800, fontSize:13,
              color: i < 3 ? "var(--blue-3)" : "var(--text-3)",
              border: i < 3 ? "1px solid rgba(37,99,235,0.25)" : "1px solid var(--border)",
            }}>#{i+1}</div>

            {/* Info */}
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:5, flexWrap:"wrap" }}>
                <span style={{ fontFamily:"Syne", fontWeight:700, fontSize:16, color:"var(--text-1)" }}>
                  {c.name || `Candidate ${c.id}`}
                </span>
                {c.seniority_level && (
                  <span className={`badge badge-${c.seniority_level === "senior" ? "blue" : c.seniority_level === "mid" ? "teal" : "gray"}`}>
                    {c.seniority_level}
                  </span>
                )}
                <PassivityBadge score={c.passivity_score} label={c.score_breakdown?.passivity_label || "—"} />
              </div>
              <div style={{ fontSize:12, color:"var(--text-2)", marginBottom:6 }}>
                {c.current_title && <span>{c.current_title}</span>}
                {c.current_company && <span> · {c.current_company}</span>}
                {c.years_experience > 0 && <span> · {c.years_experience}y exp</span>}
              </div>
              {c.skills && (
                <div style={{ display:"flex", gap:5, flexWrap:"wrap" }}>
                  {c.skills.split(",").slice(0, 5).map(s => (
                    <span key={s} className="badge badge-gray" style={{ fontSize:10 }}>{s.trim()}</span>
                  ))}
                </div>
              )}
            </div>

            {/* Scores */}
            <div style={{ display:"flex", gap:16, alignItems:"center", flexShrink:0 }}>
              <div style={{ textAlign:"center" }}>
                <ScoreRing score={c.fit_score} color="var(--blue-2)" />
                <div style={{ fontSize:9, color:"var(--text-3)", marginTop:4, fontFamily:"Syne", fontWeight:700, textTransform:"uppercase" }}>Fit</div>
              </div>
              <div style={{ textAlign:"center" }}>
                <ScoreRing score={c.passivity_score} color="#F59E0B" />
                <div style={{ fontSize:9, color:"var(--text-3)", marginTop:4, fontFamily:"Syne", fontWeight:700, textTransform:"uppercase" }}>Passivity</div>
              </div>
            </div>

            {/* Actions */}
            <div style={{ display:"flex", gap:8, flexShrink:0 }}>
              <button className="btn btn-ghost" style={{ padding:"7px 12px", fontSize:12 }}
                onClick={() => viewCV(c.id, c.source_file)}>
                View CV
              </button>
              <button className="btn btn-ghost" style={{ padding:"7px 12px", fontSize:12 }}
                onClick={() => setSelected(c.score_breakdown)}>
                Explain
              </button>
              <button onClick={() => toggleShortlist(c)} style={{
                padding:"7px 14px", borderRadius:8, fontSize:12, cursor:"pointer",
                fontFamily:"Syne", fontWeight:700, border:"none", transition:"all 0.2s",
                background: shortlisted.has(c.id) ? "rgba(37,99,235,0.2)" : "var(--navy-3)",
                color: shortlisted.has(c.id) ? "var(--blue-3)" : "var(--text-2)",
                borderWidth:1, borderStyle:"solid",
                borderColor: shortlisted.has(c.id) ? "rgba(37,99,235,0.35)" : "var(--border)",
              }}>
                {shortlisted.has(c.id) ? "✓ Shortlisted" : "+ Shortlist"}
              </button>
            </div>
          </div>
        ))}

        {candidates.length === 0 && (
          <div style={{ textAlign:"center", padding:60, color:"var(--text-3)" }}>
            <div style={{ fontSize:36, marginBottom:12 }}>🔍</div>
            <div style={{ fontFamily:"Syne", fontSize:16 }}>No candidates match the current filters</div>
          </div>
        )}
      </div>

      {selected && <ExplainPanel breakdown={selected} onClose={() => setSelected(null)} />}
    </div>
  );
}
